class Warehouse:
    DEFAULT_STATUS = 'Shipped'
    INSUFFICIENT_STOCK = False
    PRODUCT_NAME_KEY = 'name'
    PRODUCT_QUANTITY_KEY = 'quantity'
    PRODUCT_ID_KEY = 'product_id'
    ORDER_STATUS_KEY = 'status'

    def __init__(self):
        self._inventory = {}  # Product ID: Product
        self._orders = {}  # Order ID: Order

    def add_product(self, product_id, name, quantity):
        if self.has_product(product_id):
            self.increment_product_quantity(product_id, quantity)
        else:
            self.inventory[product_id] = {self.PRODUCT_NAME_KEY: name, self.PRODUCT_QUANTITY_KEY: quantity}

    def update_product_quantity(self, product_id, quantity):
        if self.has_product(product_id):
            self.increment_product_quantity(product_id, quantity)

    def get_product_quantity(self, product_id):
        if self.has_product(product_id):
            return self.inventory[product_id][self.PRODUCT_QUANTITY_KEY]
        return self.INSUFFICIENT_STOCK

    def create_order(self, order_id, product_id, quantity):
        if self.has_sufficient_stock(product_id, quantity):
            self.deduct_product_quantity(product_id, quantity)
            self.orders[order_id] = {
                self.PRODUCT_ID_KEY: product_id,
                self.PRODUCT_QUANTITY_KEY: quantity,
                self.ORDER_STATUS_KEY: self.DEFAULT_STATUS
            }
        else:
            return self.INSUFFICIENT_STOCK

    def change_order_status(self, order_id, status):
        if self.has_order(order_id):
            self.orders[order_id][self.ORDER_STATUS_KEY] = status
        else:
            return self.INSUFFICIENT_STOCK

    def track_order(self, order_id):
        if self.has_order(order_id):
            return self.orders[order_id][self.ORDER_STATUS_KEY]
        return self.INSUFFICIENT_STOCK

    @property
    def inventory(self):
        return self._inventory

    @property
    def orders(self):
        return self._orders

    def has_product(self, product_id):
        return product_id in self._inventory

    def has_order(self, order_id):
        return order_id in self._orders

    def has_sufficient_stock(self, product_id, quantity):
        current_quantity = self.get_product_quantity(product_id)
        return current_quantity is not self.INSUFFICIENT_STOCK and current_quantity >= quantity

    def increment_product_quantity(self, product_id, quantity):
        self._inventory[product_id][self.PRODUCT_QUANTITY_KEY] += quantity

    def deduct_product_quantity(self, product_id, quantity):
        self._inventory[product_id][self.PRODUCT_QUANTITY_KEY] -= quantity
